  final boolean[] committed={false};
  Runnable commit=()->{if(committed[0]||disposed||web==null)return;committed[0]=true;String text=field.getText().toString();if(textEntry!=null)textEntry.dismiss();web.evaluateJavascript("(function(){var e=document.getElementById("+JSONObject.quote(id)+");if(!e)return;e.value="+JSONObject.quote(text)+";e.dispatchEvent(new Event('input',{bubbles:true}));e.dispatchEvent(new Event('change',{bubbles:true}));"+(search?"e.dispatchEvent(new Event('search',{bubbles:true}));":id.equals("prayer-city")?"var b=document.getElementById('prayer-search');if(b)b.click();":"")+"})()",null);};
  textEntry=new android.app.AlertDialog.Builder(this).setTitle(UiSettings.text(this,search?"بحث":"كتابة",search?"Search":"Text input")).setView(SystemTextInput.wrap(this,field,false)).setPositiveButton(UiSettings.text(this,search?"بحث":"تم",search?"Search":"Done"),(d,w)->commit.run()).setNegativeButton(UiSettings.text(this,"إلغاء","Cancel"),null).create();
  textEntry.setOnDismissListener(d->{textEntry=null;if(!disposed&&web!=null)web.evaluateJavascript("(function(){if(window.IptvUI)IptvUI.keyboardClosed();var e=document.getElementById("+JSONObject.quote(id)+");if(e)e.focus();})()",null);});
  field.setOnEditorActionListener((v,action,event)->{if(event!=null&&event.getKeyCode()==android.view.KeyEvent.KEYCODE_ENTER){if(event.getAction()==android.view.KeyEvent.ACTION_UP)commit.run();return true;}if(action==android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH||action==android.view.inputmethod.EditorInfo.IME_ACTION_DONE||action==android.view.inputmethod.EditorInfo.IME_ACTION_GO){commit.run();return true;}return false;});
  final android.app.AlertDialog dialog=textEntry;
