 private void showReadyKeyboard(long serial,int attempt){if(disposed||serial!=keyboardRequest||isFinishing()||web==null)return;android.view.inputmethod.InputMethodManager ime=(android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE);if(ime==null)return;if(!web.hasWindowFocus()||!web.onCheckIsTextEditor()){if(attempt<40)web.postDelayed(()->showReadyKeyboard(serial,attempt+1),50);return;}ime.restartInput(web);if(ime.showSoftInput(web,0)){watchKeyboard(serial,false,0);}else if(attempt<40)web.postDelayed(()->showReadyKeyboard(serial,attempt+1),50);}
 private void watchKeyboard(long serial,boolean seen,int ticks){if(disposed||serial!=keyboardRequest||web==null||isFinishing()||android.os.Build.VERSION.SDK_INT<30)return;android.view.WindowInsets insets=web.getRootWindowInsets();boolean shown=insets!=null&&insets.isVisible(android.view.WindowInsets.Type.ime());if(shown)imeVisible=true;if(seen&&!shown){imeState(false);return;}if(!seen&&!shown&&ticks>=12)return;web.postDelayed(()->watchKeyboard(serial,seen||shown,ticks+1),120);}
