 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(vpn!=null&&vpn.result(request,result,data))return;if(request!=9678)return;if(result!=RESULT_OK||data==null||data.getData()==null){playlistImportResult(false,UiSettings.text(this,"تم إلغاء اختيار الملف.","File selection cancelled."));return;}final android.net.Uri uri=data.getData();final String name=playlistImportName;worker.execute(()->{try{IptvStore.get(this).importPlaylist(uri,name);playlistImportResult(true,UiSettings.text(this,"تم استيراد قائمة M3U وربطها.","M3U playlist imported and connected."));}catch(Exception error){String detail=error.getMessage()==null?"":error.getMessage().trim();if(detail.length()>360)detail=detail.substring(0,360);String prefix=UiSettings.text(this,"تعذر ربط الملف. ","Could not connect the file. ");playlistImportResult(false,prefix+(detail.isEmpty()?UiSettings.text(this,"اختَر قائمة M3U صالحة بروابط HTTP/HTTPS كاملة وفي حدود الحجم المسموح.","Choose a valid M3U with absolute HTTP/HTTPS media URLs within the supported size limits."):detail));}});}
